 async function loadSources(selected){if(!available()||busy)return;const key=identity,generation=epoch,sourceId=++sourceTicket;sourceData=null;invalidate();renderHolders();try{const result=validOptions(await api().options({workspaceId:selected}),selected);if(!current(key,generation)||sourceId!==sourceTicket||el('sp-business').value!==selected)return;sourceData=result;renderHolders();}catch(error){if(current(key,generation)&&sourceId===sourceTicket)status(message(error),true);}}
