 function renderLines(){el('sp-lines').innerHTML=lines.map((line,index)=>`<div class="warehouse-purchase-line"><label>Admin warehouse product<select data-sp-line="${index}" data-sp-field="productKey" required><option value="">Choose product</option>${products.map(row=>`<option value="${esc(row.productKey)}" ${row.productKey===line.productKey?'selected':''}>${esc(row.name)} · ${esc(row.sku||'')}</option>`).join('')}</select></label><label>Quantity<input data-sp-line="${index}" data-sp-field="quantity" type="number" min="1" step="1" value="${esc(line.quantity)}" required /></label><label>Acquisition / unit · USD<input data-sp-line="${index}" data-sp-field="unitCost" type="number" min="0" step="0.01" value="${esc(line.unitCost)}" required /></label><button data-sp-remove="${index}" type="button" class="text-button danger-text" ${lines.length<2?'disabled':''}>Remove</button></div>`).join('');renderTotal();}
