 function input(){const supplier=el('sp-supplier').value.trim(),purchaseDate=el('sp-date').value,source=holder(),method=el('sp-method').value,selectedWallet=wallet();if(!supplier||!/^\d{4}-\d{2}-\d{2}$/.test(purchaseDate)||!sourceData||sourceData.workspaceId!==el('sp-business').value||!source||!['Cash','Whish Money'].includes(method)||method==='Whish Money'&&!selectedWallet)throw Error('Choose supplier, date and the exact business holder and payment source.');const items=lines.map(line=>{const quantity=Number(line.quantity),raw=String(line.unitCost).trim(),unitCost=Number(raw);if(!products.some(row=>row.productKey===line.productKey)||!Number.isSafeInteger(quantity)||quantity<1||!/^\d+(?:\.\d{1,2})?$/.test(raw)||!money(unitCost))throw Error('Review every current warehouse product, whole quantity and exact acquisition price.');return {productKey:line.productKey,quantity,unitCost};});if(total()===null)throw Error('The purchase exceeds the supported amount.');return {requestId:crypto.randomUUID(),supplier,purchaseDate,items,sourceWorkspaceId:sourceData.workspaceId,sourceAccountKey:source.accountKey,paymentMethod:method,sourceWalletId:method==='Whish Money'?selectedWallet.id:'',deductWhishFee:method==='Whish Money'&&el('sp-fee').checked,note:el('sp-note').value.trim()};}
 function itemProof(items){if(!Array.isArray(items)||!items.length)return null;const grouped=new Map();for(const row of items){if(!id(row?.productKey)||!Number.isSafeInteger(row.quantity)||row.quantity<1||!money(row.unitCost))return null;const prior=grouped.get(row.productKey);if(prior&&prior.cost!==cents(row.unitCost))return null;const quantity=(prior?.quantity||0)+row.quantity;if(!Number.isSafeInteger(quantity))return null;grouped.set(row.productKey,{productKey:row.productKey,quantity,cost:cents(row.unitCost)});}return JSON.stringify([...grouped.values()].sort((a,b)=>a.productKey.localeCompare(b.productKey)));}
 function validPreview(result,planned){const expected=planned.items.reduce((sum,row)=>sum+cents(row.unitCost)*row.quantity,0),source=result?.source;if(!result||result.requestId!==planned.requestId||!id(result.token)||!money(result.total)||cents(result.total)!==expected||!itemProof(result.items)||itemProof(result.items)!==itemProof(planned.items)||!money(result.whishFee)||cents(result.whishFee)!==(planned.deductWhishFee?Math.round(expected/100):0)||!balance(result.balanceBefore)||!balance(result.balanceAfter)||cents(result.balanceBefore)-expected!==cents(result.balanceAfter)||result.supplier!==planned.supplier||result.purchaseDate!==planned.purchaseDate||source?.workspaceId!==planned.sourceWorkspaceId||source?.accountKey!==planned.sourceAccountKey||source?.paymentMethod!==planned.paymentMethod||planned.paymentMethod==='Whish Money'&&source.wallet?.id!==planned.sourceWalletId||planned.paymentMethod==='Cash'&&source.wallet!==null||source.balanceCents!==cents(result.balanceBefore))throw Error('The reviewed stock purchase or exact money source could not be verified.');if(cents(result.balanceBefore)<expected)throw Error('The selected holder has insufficient money in this exact source.');return result;}
 async function preview(event){event.preventDefault();if(!available()||locked())return;let planned;try{planned=input();}catch(error){status(message(error),true);return;}const key=identity,generation=epoch;busy=true;invalidate();render();try{const result=validPreview(await api().preview(planned),planned);if(!current(key,generation))return;reviewed={input:planned,preview:result};el('sp-preview').innerHTML=`<p><strong>${esc(planned.supplier)}</strong> · ${esc(planned.purchaseDate)}</p><p>${planned.items.length} physical product line(s) → Admin central stock</p><div class="sp-preview-grid"><div><span>Business / actual holder</span><strong>${esc(businesses.find(row=>row.id===planned.sourceWorkspaceId)?.name||planned.sourceWorkspaceId)}</strong><small>${esc(result.source.fullName)} · ${esc(result.source.role)}</small></div><div><span>Payment source</span><strong>${esc(planned.paymentMethod)}</strong><small>${esc(result.source.wallet?[result.source.wallet.label,result.source.wallet.number].join(' · '):'This holder’s cash drawer')}</small></div><div><span>Recorded balance before</span><strong>${usd(result.balanceBefore)}</strong></div><div><span>Purchase outflow</span><strong>−${usd(result.total)}</strong></div><div><span>Recorded balance after</span><strong>${usd(result.balanceAfter)}</strong></div><div><span>Optional Whish fee · profit only</span><strong>${usd(result.whishFee)}</strong></div></div><p class="field-note">No additional funding-spend deduction, customer revenue or business product debt. Confirm only a purchase/payment actually made separately.</p>`;el('sp-review-panel').classList.remove('hidden');el('sp-review-panel').scrollIntoView({block:'nearest',behavior:'smooth'});status('Review the source and stock before confirming.');}catch(error){if(current(key,generation))status(message(error),true);}finally{if(current(key,generation)){busy=false;render();}}}
